import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Crimson/SeaStore for Ceph Developer Summit - Vampire","description":"","frontmatter":{"title":"Crimson/SeaStore for Ceph Developer Summit - Vampire","date":"2026-08-14T00:00:00.000Z","updated":"2026-08-15T00:00:00.000Z","tags":["Crimson","Ceph","性能优化","BlueStore","Cephadm"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Crimson_SeaStore_for_Ceph_Developer_Summit_-_Vampire.md","filePath":"posts/2026/Crimson_SeaStore_for_Ceph_Developer_Summit_-_Vampire.md","lastUpdated":null}'),i={name:"posts/2026/Crimson_SeaStore_for_Ceph_Developer_Summit_-_Vampire.md"};function l(n,e,s,m,d,p){return r(),a("div",null,[...e[0]||(e[0]=[o('<h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>本次 Ceph Developer Summit（Vampire 版本）会议聚焦于 Crimson/SeaStore 的现状与 Vampire 版本规划。主讲人 Mattan 介绍了 Vampire 版本的核心目标：不是引入大量新功能，而是缩小 Crimson 当前能力与预期能力之间的差距，提升整体可用性与易用性。</p><h2 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h2><h3 id="vampire-版本核心目标" tabindex="-1">Vampire 版本核心目标 <a class="header-anchor" href="#vampire-版本核心目标" aria-label="Permalink to &quot;Vampire 版本核心目标&quot;">​</a></h3><p>Vampire 版本的重点方向围绕以下四个方面展开：</p><ul><li><strong>老客户端支持（Old Client Support）</strong>：提升对遗留客户端的兼容性</li><li><strong>部署便捷性（Deployment Ease）</strong>：降低部署门槛，简化操作流程</li><li><strong>性能（Performance）</strong>：持续提升 SeaStore 性能表现</li><li><strong>可观测性（Visibility）</strong>：增强内部状态的可见性与可测量性</li></ul><h3 id="性能优化进展" tabindex="-1">性能优化进展 <a class="header-anchor" href="#性能优化进展" aria-label="Permalink to &quot;性能优化进展&quot;">​</a></h3><p>在 Umbrella 版本中已经完成了大量为 Vampire 铺垫的性能工作，主要包括：</p><ul><li>通过多个 PR 实现了显著的<strong>吞吐量（throughput）提升</strong>和<strong>延迟（latency）降低</strong></li><li>支持<strong>多 reactor</strong> 并发处理，提升并行能力</li><li>识别并着手优化 <strong>PG log overhead</strong>，细化 transaction path 的性能分解</li><li>改进内存分配策略，保留局部性（memory locality），由团队成员 Cotilla 负责推进</li><li>新增专用 benchmark 工具，支持对 SeaStore 的精细化性能测试</li><li>在 Umbrella 中引入了基于性能数字的 <strong>PR 性能门控（performance gate）</strong>，防止性能退化合并入主干</li></ul><h3 id="大规模测试计划" tabindex="-1">大规模测试计划 <a class="header-anchor" href="#大规模测试计划" aria-label="Permalink to &quot;大规模测试计划&quot;">​</a></h3><ul><li>当前正在对 Umbrella RC（Release Candidate）进行大规模测试</li><li>计划在大规模测试中对比 Crimson 与 Classic OSD 的表现（sweeping reactor vs classic）</li><li>测试结果将直接影响 Vampire 版本的优先级排列，特别是在可部署性和客户端支持方面的差距识别</li></ul><h3 id="功能差距补全-feature-gaps" tabindex="-1">功能差距补全（Feature Gaps） <a class="header-anchor" href="#功能差距补全-feature-gaps" aria-label="Permalink to &quot;功能差距补全（Feature Gaps）&quot;">​</a></h3><p>以下功能将在 Vampire 版本中落地或继续推进：</p><table tabindex="0"><thead><tr><th>功能</th><th>状态</th></tr></thead><tbody><tr><td>mClock 完整支持</td><td>已合并到 main，将随 Vampire 发布</td></tr><tr><td>Erasure Coding 支持</td><td>进行中（当前仅支持 replicated pool）</td></tr><tr><td>Scrub 后台调度</td><td>已有基本实现，需接入后台调度机制</td></tr><tr><td>PG splitting（Pool 扩容）</td><td>已支持</td></tr><tr><td>PG merging（Pool 缩容）</td><td>计划纳入 Vampire</td></tr><tr><td>Replication path 瓶颈排查</td><td>关注 peering 阶段潜在瓶颈</td></tr></tbody></table><h3 id="cephadm-部署改进" tabindex="-1">Cephadm 部署改进 <a class="header-anchor" href="#cephadm-部署改进" aria-label="Permalink to &quot;Cephadm 部署改进&quot;">​</a></h3><p>Umbrella 版本已大幅简化 Crimson 的部署方式：</p><ul><li>无需特殊 flag、专用构建或镜像，直接使用上游标准镜像即可部署 Crimson</li><li>部署命令示例：添加 <code>--crimson</code> 或 <code>--object-store</code> 参数即可选择使用 SeaStore</li></ul><p>Vampire 版本计划进一步补全：</p><ul><li><strong>Prometheus metrics 支持</strong>：暴露 Crimson reactor 的内部运行状态，增强可观测性</li></ul><h3 id="seastore-后端选择-rbm-vs-segmented" tabindex="-1">SeaStore 后端选择：RBM vs Segmented <a class="header-anchor" href="#seastore-后端选择-rbm-vs-segmented" aria-label="Permalink to &quot;SeaStore 后端选择：RBM vs Segmented&quot;">​</a></h3><p>SeaStore 目前有两种底层存储后端实现：</p><ul><li><strong>Segmented（分段式）</strong>：模拟 SSD FTL 的内部工作方式，理论上可减少写放大（write amplification），但需要对底层设备特性有更精确的启发式判断</li><li><strong>Random Block Manager（RBM，随机块管理器）</strong>：更通用，适合各类场景</li></ul><p><strong>决定事项</strong>：Vampire 版本将把 <strong>RBM 设为默认后端</strong>。原因是 RBM 当前在通用部署场景中表现更稳定，易用性更高。Segmented 后端仍保留，未来在 ZNS 设备（Zoned Namespace SSD）场景下预期会更有优势，届时无需猜测设备内部 zone 结构。两种后端在部署前仍可自由选择切换。</p><h2 id="问答环节" tabindex="-1">问答环节 <a class="header-anchor" href="#问答环节" aria-label="Permalink to &quot;问答环节&quot;">​</a></h2><p><strong>Q：为什么 RBM 比 Segmented 后端表现更好？</strong></p><p>Mattan 回答：这仍是一个开放性问题。理论上 Segmented 应该能取得更好效果，但目前对底层设备的启发式匹配还不够成熟。RBM 作为通用方案当前更易于使用，Segmented 在 ZNS 等设备上仍有潜力。两种实现都将持续维护。</p><h2 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h2><ol><li><strong>发布 Umbrella RC 测试结果</strong>：与 Classic OSD 的对比数据将作为 Vampire 重点方向的重要依据</li><li><strong>推进 Vampire 功能落地</strong>：包括 Erasure Coding、Scrub 调度、PG merging 等</li><li><strong>继续性能可见性工作</strong>：完善 Prometheus 集成，展示 reactor 内部状态</li><li><strong>切换 RBM 为默认后端</strong>：在 Vampire 版本中完成</li><li><strong>鼓励社区评估</strong>：邀请用户通过 Cephadm 部署 Crimson 并反馈，可在 Crimson Slack channel 寻求支持</li></ol>',28)])])}const c=t(i,[["render",l]]);export{g as __pageData,c as default};
